kdrop-filter:blur(8px);border-radius:3px}.team-score{display:flex;align-items:center;gap:10px}.team-score>div{display:flex;flex-direction:column;align-items:flex-start;gap:0}.team-score.opponent>div{align-items:flex-end}.team-score small{font:8px var(--mono);letter-spacing:1.2px;color:#b9c3bc;white-space:nowrap}.team-score strong{font:600 24px/.95 var(--display);letter-spacing:.5px}.team-crest{width:30px;height:30px;display:grid;place-items:center;clip-path:polygon(50% 0,95% 16%,90% 72%,50% 100%,10% 72%,5% 16%);font:700 14px var(--display)}.crest-home{color:var(--ink);background:var(--acid)}.crest-away{background:#e8e4da;color:#202720;font:700 9px var(--mono)}.score-divider{display:flex;flex-direction:column;align-items:center;gap:1px;color:var(--acid);font:13px var(--mono)}.score-divider small{color:#aab5ac;font-size:8px;white-space:nowrap}.round-progress{position:absolute;z-index:3;top:198px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px}.progress-line{width:27px;height:1px;background:rgba(255,255,255,.34)}.shot-dots{display:flex;gap:7px}.shot-dot{height:6px;width:6px;border-radius:50%;background:rgba(255,255,255,.34)}.shot-dot.done{background:var(--acid);box-shadow:0 0 7px #d5ff3f77}.shot-dot.miss{background:var(--orange)}.shot-dot.active{outline:1px solid var(--acid);outline-offset:3px}.left-note{position:absolute;z-index:3;top:47%;left:4.3%;display:flex;gap:12px;align-items:center;transform:translateY(-50%);opacity:.85}.note-index{font:500 10px var(--mono);color:var(--acid);border-right:1px solid rgba(255,255,255,.3);padding-right:10px}.left-note div{display:flex;flex-direction:column;gap:4px}.left-note strong{font:700 12px var(--display);letter-spacing:1px}.left-note small{font:8px var(--mono);letter-spacing:1px;color:#c3cdc5}.aim-label{z-index:4;position:absolute;left:50%;top:43%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:8px;color:#f5f2e9cc;font:9px var(--mono);letter-spacing:1.2px;pointer-events:none;transition:opacity .2s}.aim-cross{color:var(--acid);font:18px var(--body);text-shadow:0 0 8px #d5ff3f88}.shot-callout{position:absolute;z-index:5;left:50%;top:43%;transform:translate(-50%,-50%) scale(.8);font:900 clamp(42px,8vw,100px)/.8 var(--display);letter-spacing:2px;color:var(--acid);text-shadow:0 5px 25px #04100b99;opacity:0;pointer-events:none;white-space:nowrap}.shot-callout.show{animation:callout 1.15s ease-out forwards}@keyframes callout{0%{opacity:0;transform:translate(-50%,-50%) scale(.72)}15%{opacity:1;transform:translate(-50%,-50%) scale(1.05)}70%{opacity:1}100%{opacity:0;transform:translate(-50%,-58%) scale(1)}}.trajectory-hint{position:absolute;z-index:3;left:50%;top:64%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;font:8px var(--mono);letter-spacing:1.3px;color:#f4f3e5b3}.hint-line{width:16px;height:1px;background:var(--acid)}.bottom-hud{position:absolute;z-index:4;bottom:39px;left:50%;transform:translateX(-50%);width:min(650px,86vw);height:78px;display:grid;grid-template-columns:1fr 1.08fr 1fr;align-items:center;gap:22px;padding:0 20px;background:rgba(7,16,13,.83);border:1px solid rgba(255,255,255,.22);backdrop-filter:blur(14px);border-radius:3px;box-shadow:0 12px 50px #0005}.stat-block{display:flex;flex-direction:column;gap:7px}.stat-label{font:8px var(--mono);letter-spacing:1.2px;color:#c0cac1}.power-row{display:flex;align-items:center;gap:8px}.power-row>strong{font:500 10px var(--mono);min-width:28px}.power-track{position:relative;height:5px;width:100%;background:#68716a66;border-radius:8px;overflow:visible}.power-fill{height:100%;width:0;background:linear-gradient(90deg,#83ca49,var(--acid),#ff814b);border-radius:8px;transition:width .08s linear;box-shadow:0 0 10px #d5ff3f55}.power-mark{position:absolute;top:-2px;height:9px;width:1px;background:#d3d9d2aa}.mark-1{left:60%}.mark-2{left:80%}.mark-3{left:95%}.power-caption{display:flex;justify-content:space-between;color:#86938a;font:7px var(--mono);letter-spacing:.4px}.shoot-button{height:48px;display:flex;align-items:center;justify-content:center;gap:11px;background:var(--acid);border:0;border-radius:2px;color:#121a0d;cursor:pointer;transition:filter .15s,transform .15s;touch-action:none}.shoot-button:hover{filter:brightness(1.08);transform:translateY(-1px)}.shoot-button.charging{filter:brightness(1.18);box-shadow:0 0 19px #d5ff3f77;transform:scale(.98)}.shoot-icon{font-size:19px;transform:rotate(-30deg)}.shoot-copy{display:flex;flex-direction:column;align-items:flex-start;gap:1px}.shoot-copy strong{font:800 15px/.95 var(--display);letter-spacing:1px}.shoot-copy small{font:7px var(--mono);letter-spacing:.4px}.shoot-key{border:1px solid #22301855;padding:4px 5px;border-radius:2px;font:7px var(--mono)}.bottom-meta{display:flex;align-items:center;justify-content:flex-end;gap:17px}.wind{display:flex;align-items:center;gap:7px}.wind-icon{color:var(--acid);font-size:18px}.wind>div{display:flex;flex-direction:column;gap:2px}.wind small,.accuracy small{font:7px var(--mono);letter-spacing:.8px;color:#aab4ab}.wind strong{font:500 11px var(--mono)}.wind strong i{font-style:normal;color:#aab4ab;font-size:7px}.accuracy{display:flex;flex-direction:column;align-items:center;gap:2px}.accuracy-ring{width:32px;height:32px;border:1px solid #d5ff3f88;border-radius:50%;display:grid;place-items:center;color:var(--acid);font:8px var(--mono)}.side-tip{position:absolute;z-index:3;bottom:18px;left:4.3%;font:8px var(--mono);color:#c5ccc6;letter-spacing:.7px}.tip-key{color:#e3e7df}.tip-sep{color:#637067;margin:0 5px}.toast{position:absolute;z-index:6;left:50%;bottom:132px;transform:translate(-50%,10px);padding:9px 14px;border:1px solid #d5ff3f55;background:#07100edb;font:9px var(--mono);letter-spacing:1px;color:var(--acid);opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.restart-button{position:absolute;z-index:5;right:4.3%;bottom:53px;width:36px;height:36px;border-radius:50%;border:1px solid #ffffff44;background:#06100d55;color:#f1f1e8;font-size:20px;cursor:pointer}.overlay{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:rgba(3,10,8,.50);backdrop-filter:blur(2px);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{position:relative;width:min(460px,calc(100vw - 42px));padding:36px 39px 31px;background:rgba(8,19,15,.88);border:1px solid rgba(255,255,255,.24);box-shadow:0 20px 80px #0007}.intro-card:before,.result-card:before{content:'';position:absolute;left:-1px;top:-1px;width:50px;height:3px;background:var(--acid)}.eyebrow{display:flex;align-items:center;gap:9px;color:#d5ded6;font:9px var(--mono);letter-spacing:1.8px}.eyebrow>span{width:6px;height:6px}.overlay h1{font:900 clamp(65px,9vw,95px)/.79 var(--display);letter-spacing:1px;margin:29px 0 18px}.overlay h1 em{font-style:normal;color:var(--acid)}.overlay-card>p{font-size:12px;color:#bac4bc;margin:0 0 27px}.intro-rule{display:flex;align-items:center;gap:10px;margin-bottom:22px;font:8px var(--mono);color:var(--acid)}.intro-rule i{height:1px;width:50px;background:#ffffff55}.intro-rule .rule-caption{color:#a7b0a7;letter-spacing:1px;margin-left:4px}.primary-button{width:100%;height:51px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;border:none;background:var(--acid);color:#10170d;font:800 15px var(--display);letter-spacing:1.1px;cursor:pointer;transition:filter .15s}.primary-button:hover{filter:brightness(1.1)}.primary-button span{font:18px var(--body)}.intro-controls{display:flex;justify-content:center;gap:19px;margin-top:22px;color:#aeb8af;font:8px var(--mono);letter-spacing:.7px}.intro-controls span:first-letter{color:var(--acid)}.overlay-foot{position:absolute;bottom:27px;left:4.2%;right:4.2%;display:flex;justify-content:space-between;color:#d3dbd4a0;font:8px var(--mono);letter-spacing:1.4px}.result-card{text-align:center}.result-card .eyebrow{justify-content:center}.result-kicker{margin-top:30px;color:var(--acid);font:10px var(--mono);letter-spacing:2px}.result-card h2{font:900 clamp(53px,8vw,78px)/.9 var(--display);margin:8px 0 10px}.result-card>p{margin:0 0 24px}.result-score{display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:23px}.result-score span{color:#9ba79e;font:8px var(--mono);letter-spacing:1px}.result-score strong{font:700 27px var(--display)}.result-best{margin-top:19px;color:#98a49a;font:8px var(--mono);letter-spacing:1px}.result-best strong{color:var(--acid);font-size:11px;margin-left:5px}.mobile-controls{display:none}
@media(max-width:700px){.topbar{height:66px;padding:0 19px}.brand-mark{font-size:28px}.brand-name{font-size:7px}.match-pill{padding:8px 10px;gap:8px;font-size:8px}.sound-button{font-size:0}.sound-button span:first-child{font-size:20px}.scoreboard{top:82px;padding:8px 14px;gap:18px}.team-crest{width:25px;height:25px}.team-score strong{font-size:21px}.team-score small{font-size:7px}.round-progress{top:145px}.left-note{display:none}.aim-label{top:39%;font-size:8px}.trajectory-hint{top:59%}.bottom-hud{bottom:calc(18px + env(safe-area-inset-bottom));width:calc(100% - 24px);height:70px;padding:0 12px;grid-template-columns:1fr 1.05fr .65fr;gap:10px}.stat-label{font-size:7px}.shoot-button{height:46px;gap:6px}.shoot-icon{font-size:16px}.shoot-copy strong{font-size:13px}.shoot-copy small{font-size:6px}.shoot-key{display:none}.bottom-meta{gap:0}.wind{display:none}.accuracy-ring{width:30px;height:30px}.accuracy small{font-size:6px}.power-caption{font-size:6px}.side-tip{display:none}.restart-button{right:13px;bottom:102px;width:31px;height:31px;font-size:17px}.toast{bottom:106px}.overlay-card{padding:30px 26px 26px}.overlay-foot{bottom:calc(14px + env(safe-area-inset-bottom));font-size:7px}.intro-controls{gap:13px;font-size:7px}.overlay-card>p{font-size:11px}.mobile-controls{display:flex;position:absolute;z-index:4;left:17px;bottom:calc(100px + env(safe-area-inset-bottom));gap:7px}.mobile-controls button{height:39px;min-width:40px;border:1px solid #ffffff44;border-radius:3px;background:#07100e8c;color:white;font:16px var(--body);touch-action:none}.mobile-controls #mobileShoot{display:none}.game-shell.playing .mobile-controls #mobileShoot{display:block;background:var(--acid);border-color:var(--acid);color:#111;font:800 10px var(--mono);padding:0 13px}.game-shell.playing .shoot-key{display:none}}
@media(max-height:650px) and (min-width:701px){.topbar{height:65px}.scoreboard{top:82px}.round-progress{top:164px}.bottom-hud{bottom:19px}.overlay-foot{bottom:12px}.left-note{top:43%}.trajectory-hint{top:65%}.overlay-card{padding-top:25px;padding-bottom:22px}.overlay h1{font-size:70px;margin:20px 0 12px}}

